actionConfiguration.body:
function (startTimeStr, durationRaw, isBlocked) {
  const startMs = AvailabilityEngine.parseDateTimeMs(startTimeStr);
  if (startMs === null) {
    return {
      available: false,
      status: "Validation Error",
      reasonCode: "INVALID_START_TIME",
      message: "Please select a valid start date and time (YYYY-MM-DD HH:MM) (AC6)."
    };
  }
  const nowMs = AvailabilityEngine.parseDateTimeMs(AvailabilityEngine.referenceNow);
  if (durationRaw === null || durationRaw === undefined || typeof durationRaw === "boolean" || String(durationRaw).trim() === "") {
    return {
      available: false,
      status: "Validation Error",
      reasonCode: "INVALID_DURATION",
      message: "Duration must be a valid number of minutes between 1 and 120 (AC2, AC6)."
    };
  }
  const duration = Number(durationRaw);
  if (!Number.isFinite(duration)) {
    return {
      available: false,
      status: "Validation Error",
      reasonCode: "INVALID_DURATION",
      message: "Duration must be a finite numeric value (AC2, AC6)."
    };
  }
  if (duration <= 0) {
    return {
      available: false,
      status: "Validation Error",
      reasonCode: "DURATION_TOO_SHORT",
      message: "Duration must be greater than 0 minutes (AC2)."
    };
  }
  if (duration > 120) {
    return {
      available: false,
      status: "Validation Error",
      reasonCode: "DURATION_TOO_LONG",
      message: "Duration cannot exceed 120 minutes (AC2)."
    };
  }
  if (startMs <= nowMs) {
    return {
      available: false,
      status: "Validation Error",
      reasonCode: "START_TIME_IN_PAST",
      message: `Start time must be in the future (after ${AvailabilityEngine.referenceNow}) (AC1).`
    };
  }
  if (Boolean(isBlocked)) {
    return {
      available: false,
      status: "Unavailable",
      reasonCode: "ROOM_BLOCKED",
      message: `${AvailabilityEngine.roomName} is currently blocked for maintenance or administrative hold (AC4).`
    };
  }
  const reqEndMs = startMs + duration * 60 * 1000;
  for (const bk of AvailabilityEngine.fictionalBookings) {
    const bkStartMs = AvailabilityEngine.parseDateTimeMs(bk.start);
    const bkEndMs = AvailabilityEngine.parseDateTimeMs(bk.end);
    if (startMs < bkEndMs && reqEndMs > bkStartMs) {
      return {
        available: false,
        status: "Unavailable",
        reasonCode: "BOOKING_OVERLAP",
        message: `Requested slot overlaps with existing booking ${bk.id} (${AvailabilityEngine.formatTime(bkStartMs)}–${AvailabilityEngine.formatTime(bkEndMs)}) (AC3).`
      };
    }
  }
  return {
    available: true,
    status: "Available",
    reasonCode: "AVAILABLE",
    message: `${AvailabilityEngine.roomName} is available from ${startTimeStr} to ${AvailabilityEngine.formatTime(reqEndMs)} (${duration} min).`
  };
}

