        status: "Validation Error",
        reasonCode: "DURATION_TOO_LONG",
        message: "Duration cannot exceed 120 minutes (AC2)."
      };
    }

    if (startMs <= nowMs) {
      return {
        available: false,
        status: "Validation Error",
        reasonCode: "START_TIME_IN_PAST",
        message: `Start time must be in the future (after ${this.referenceNow}) (AC1).`
      };
    }

    if (Boolean(isBlocked)) {
      return {
        available: false,
        status: "Unavailable",
        reasonCode: "ROOM_BLOCKED",
        message: `${this.roomName} is currently blocked for maintenance or administrative hold (AC4).`
      };
    }

    const reqEndMs = startMs + duration * 60 * 1000;
    for (const bk of this.fictionalBookings) {
      const bkStartMs = this.parseDateTimeMs(bk.start);
      const bkEndMs = this.parseDateTimeMs(bk.end);
      if (startMs < bkEndMs && reqEndMs > bkStartMs) {
        return {
          available: false,
          status: "Unavailable",
          reasonCode: "BOOKING_OVERLAP",
          message: `Requested slot overlaps with existing booking ${bk.id} (${this.formatTime(bkStartMs)}–${this.formatTime(bkEndMs)}) (AC3).`
        };
      }
    }

    return {
      available: true,
      status: "Available",
      reasonCode: "AVAILABLE",
      message: `${this.roomName} is available from ${startTimeStr} to ${this.formatTime(reqEndMs)} (${duration} min).`
    };
  },

  async runCheck () {
    const decision = this.evaluate(
      dpStartTime.formattedDate,
      inpDuration.text,
      swRoomBlocked.isSwitchedOn
    );
    // persist = false keeps state in session memory only, avoiding persistent localStorage exposure
    await storeValue("lastResult", decision, false);
    return decision;
  }
};

